addOverlayWidget(widget) {
        const widgetData = {
            widget: widget,
            position: widget.getPosition()
        };
        if (this.Cb.hasOwnProperty(widget.getId())) {
            console.warn('Overwriting an overlay widget with the same id.');
        }
        this.Cb[widget.getId()] = widgetData;
        if (this.tb && this.tb.hasRealView) {
            this.tb.view.addOverlayWidget(widgetData);
        }
    }
